import csv
import io
import json
import os
import re
import sys
from collections import Counter


def norm_id(text):
    return str(text).strip().casefold()


def norm_text(text):
    chars = [ch if ch.isalnum() else " " for ch in str(text).casefold()]
    return " ".join("".join(chars).split())


def parse_csv(text):
    lines = text.split("\n")
    meta = {}
    pos = 0
    while pos < len(lines) and (lines[pos].startswith("#") or not lines[pos].strip()):
        line = lines[pos].strip()
        if line.startswith("#") and ":" in line:
            name, value = line[1:].split(":", 1)
            meta[name.strip().lower()] = value.strip()
        pos += 1
    rows = list(csv.reader(io.StringIO("\n".join(lines[pos:]), newline="")))
    rows = [row for row in rows if any(cell.strip() for cell in row)]
    records = []
    if not rows:
        return meta, records
    header = [cell.strip() for cell in rows[0]]
    ballot_col = header.index("ballot")
    contest_col = header.index("contest")
    rank_cols = []
    for index, name in enumerate(header):
        match = re.fullmatch(r"rank(\d+)", name)
        if match:
            rank_cols.append((int(match.group(1)), index))
    for row in rows[1:]:
        row = row + [""] * (len(header) - len(row))
        marks = []
        for rank, index in rank_cols:
            cell = row[index]
            if cell.strip() == "":
                continue
            for part in cell.split("|"):
                if part.strip() == "":
                    continue
                if part.lstrip().startswith("WI:"):
                    marks.append((rank, "wi", part.lstrip()[3:]))
                else:
                    marks.append((rank, "id", part.strip()))
        records.append((row[ballot_col].strip(), row[contest_col], marks))
    return meta, records


def parse_jsonl(text):
    meta = {}
    records = []
    first = True
    for line in text.split("\n"):
        if not line.strip():
            continue
        obj = json.loads(line)
        if first:
            meta = {key: obj[key] for key in obj}
            first = False
            continue
        marks = []
        for mark in obj.get("marks", []):
            rank = int(mark["rank"])
            if mark.get("write_in") is not None:
                marks.append((rank, "wi", mark["write_in"]))
            elif mark.get("candidate") is not None:
                marks.append((rank, "id", str(mark["candidate"]).strip()))
        records.append((obj.get("ballot"), obj.get("contest"), marks))
    return meta, records


def load_records(input_dir):
    cvr_dir = os.path.join(input_dir, "cvr")
    batches = {}
    for name in sorted(os.listdir(cvr_dir)):
        path = os.path.join(cvr_dir, name)
        if not os.path.isfile(path):
            continue
        if name.endswith(".csv"):
            parser = parse_csv
        elif name.endswith(".jsonl"):
            parser = parse_jsonl
        else:
            continue
        with open(path, encoding="utf-8-sig", newline="") as handle:
            text = handle.read().replace("\r\n", "\n")
        meta, records = parser(text)
        batch = str(meta.get("batch", ""))
        revision = int(str(meta.get("revision", "0")).strip())
        status = str(meta.get("status", "final")).strip().lower()
        current = batches.get(batch)
        if current is None or revision > current[0]:
            batches[batch] = (revision, status, records)
    result = []
    for revision, status, records in batches.values():
        if status != "void":
            result.extend(records)
    return result


def read_rankings(marks, contest_info):
    max_ranks, withdrawn, writeins, valid = contest_info
    by_rank = {}
    for rank, kind, value in marks:
        if 1 <= rank <= max_ranks:
            by_rank.setdefault(rank, []).append((kind, value))
    seen = set()
    result = []
    for rank in range(1, max_ranks + 1):
        current = set()
        for kind, value in by_rank.get(rank, []):
            if kind == "wi":
                cand = writeins.get(norm_text(value))
                if cand is not None:
                    current.add(cand)
            else:
                current.add(norm_id(value))
        if not current:
            result.append(("skip",))
            continue
        current -= withdrawn
        if not current:
            result.append(("pass",))
            continue
        fresh = current - seen
        seen |= current
        if not fresh:
            result.append(("skip",))
        elif len(fresh) == 1:
            result.append(("choice", next(iter(fresh))))
        else:
            result.append(("over",))
    return tuple(result)


def count_ballot(ranking, continuing):
    size = len(ranking)
    index = 0
    while index < size:
        entry = ranking[index]
        kind = entry[0]
        if kind == "choice":
            if entry[1] in continuing:
                return entry[1]
        elif kind == "over":
            return None
        elif kind == "skip":
            if index + 1 >= size or ranking[index + 1][0] == "skip":
                return None
        index += 1
    return None


def tally_contest(contest, records):
    candidates = {}
    withdrawn = set()
    for cand in contest.get("candidates", []):
        key = norm_id(cand["id"])
        candidates[key] = cand["id"]
        if cand.get("status", "active") == "withdrawn":
            withdrawn.add(key)
    writeins = {}
    for wi in contest.get("write_ins", []):
        key = norm_id(wi["id"])
        candidates[key] = wi["id"]
        for text in [wi["name"]] + list(wi.get("aliases", [])):
            writeins[norm_text(text)] = key
    lot = {norm_id(cid): pos for pos, cid in enumerate(contest.get("lot_order", []))}
    info = (int(contest["max_ranks"]), withdrawn, writeins, set(candidates))
    rankings = Counter(read_rankings(marks, info) for marks in records)
    total = len(records)
    continuing = {key for key in candidates if key not in withdrawn}
    history = []
    rounds = []
    winner = None
    while True:
        votes = {key: 0 for key in continuing}
        for ranking, number in rankings.items():
            choice = count_ballot(ranking, continuing)
            if choice is not None:
                votes[choice] += number
        active = sum(votes.values())
        entry = {"round": len(rounds) + 1,
                 "tallies": {candidates[key]: votes[key] for key in continuing},
                 "exhausted": total - active, "eliminated": []}
        rounds.append(entry)
        history.append(votes)
        if active == 0:
            break
        top = [key for key in continuing if votes[key] * 2 > active]
        if top:
            winner = top[0]
            break
        if len(continuing) == 1:
            winner = next(iter(continuing))
            break
        zeros = [key for key in continuing if votes[key] == 0]
        if zeros:
            out = set(zeros)
        else:
            low = min(votes.values())
            tied = [key for key in continuing if votes[key] == low]
            for past in reversed(history[:-1]):
                if len(tied) == 1:
                    break
                low = min(past[key] for key in tied)
                tied = [key for key in tied if past[key] == low]
            if len(tied) > 1:
                tied = [max(tied, key=lambda key: lot.get(key, -1))]
            out = set(tied)
        entry["eliminated"] = sorted(candidates[key] for key in out)
        continuing -= out
    return {"contest": contest["id"], "ballots": total,
            "winner": candidates[winner] if winner is not None else None,
            "rounds": rounds}


def main():
    input_dir, output_file = sys.argv[1], sys.argv[2]
    with open(os.path.join(input_dir, "election.json"), encoding="utf-8") as handle:
        election = json.load(handle)
    by_contest = {contest["id"]: [] for contest in election["contests"]}
    for ballot, contest_id, marks in load_records(input_dir):
        if contest_id in by_contest:
            by_contest[contest_id].append(marks)
    output = {"election": election["election"],
              "contests": [tally_contest(contest, by_contest[contest["id"]])
                           for contest in election["contests"]]}
    with open(output_file, "w", encoding="utf-8") as handle:
        json.dump(output, handle, ensure_ascii=False, indent=1)


main()
